// Charts as they are edited in the spreadsheet editor: added from the toolbar for the
// selected range, selected, moved, sized and deleted with the pointer and with keys, changed
// in their dialog, saved and read again, and following rows that are inserted.
//
// No screenshots: the pixels of the canvas are read with getImageData(). Every workbook is
// generated by code. The chart is put within columns A to D (header 72 x 22, columns 64 wide,
// rows 20 high), so that a phone shows all of it; its series is given one plain colour and its
// value axis runs from 0 to 100, so that the height of a column is its value.
import type { Page } from '@playwright/test';
import { chartWorkbook, sheetData } from '../test/chart-fixtures';
import { expect, test } from './helpers';

const GREEN = [0, 176, 80];
const BLUE = [26, 115, 232];
const HEADER_WIDTH = 72;
const HEADER_HEIGHT = 22;
const COLUMN_WIDTH = 64;
const ROW_HEIGHT = 20;
/** The frame the chart is put in, CSS pixels of the canvas: A6 to the start of E19. */
const FRAME = { x: HEADER_WIDTH, y: HEADER_HEIGHT + 5 * ROW_HEIGHT, width: 4 * COLUMN_WIDTH, height: 13 * ROW_HEIGHT };
const HOME = { top: 5, left: 0, bottom: 17, right: 3 };
const MOUSE_ONLY = 'a mouse is needed';
const TOUCH_ONLY = 'a touch screen is needed';

const book = () => chartWorkbook({ sheet: sheetData([['Ad', 'Adet'], ['a', 10], ['b', 20], ['c', 40]]) });

async function mount(page: Page, bytes: Uint8Array | number[], options: Record<string, unknown> = {}): Promise<void> {
  await page.goto('/e2e/pages/editor.html');
  await page.waitForFunction(() => typeof (window as any).__mountEditor === 'function');
  await page.evaluate(
    async ({ base64, options }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountEditor(data, options, 'host');
    },
    { base64: Buffer.from(bytes as Uint8Array).toString('base64'), options: { locale: 'en-US', ...options } },
  );
  await expect(page.locator('#host .bym-canvas')).toBeVisible();
}

const view = (page: Page, code: string) => page.evaluate((code) => new Function('view', 'api', `return ${code}`)((window as any).__editor.view, (window as any).BymOffice), code);
const charts = (page: Page): Promise<any[]> => view(page, 'view.charts()') as Promise<any[]>;
const dialog = (page: Page) => page.locator('#host [data-bym-dialog="chart"]');
const field = (page: Page, name: string) => dialog(page).locator(`[data-bym-field="${name}"]`);

/** A chart of A1:B4 in the frame, with a green series and an axis from 0 to 100; it is not selected afterwards. */
async function addPlain(page: Page): Promise<void> {
  await view(
    page,
    `(view.addChart({ type: 'column', range: { top: 0, left: 0, bottom: 3, right: 1 }, anchor: ${JSON.stringify(HOME)}, legend: 'none' }),
      view.updateChart(0, { series: [{ from: 0, color: '#00B050' }], axisBounds: { min: 0, max: 100 } }),
      view.selectChart(undefined))`,
  );
}

interface Ink {
  count: number;
  /** Runs of pixel columns that hold the colour: how many pixels the fullest column of each holds. */
  runs: number[];
}

/** Looks for a colour in a box of the canvas (CSS pixels), after a forced redraw. */
function ink(page: Page, colour: number[], box: { x: number; y: number; width: number; height: number }): Promise<Ink> {
  return page.evaluate(
    ([colour, box]) => {
      const view = (window as any).__editor.view;
      view.render();
      const canvas = document.querySelector('#host .bym-canvas') as HTMLCanvasElement;
      const dpr = view.getViewState().devicePixelRatio;
      const area = box as { x: number; y: number; width: number; height: number };
      const width = Math.round(area.width * dpr);
      const height = Math.round(area.height * dpr);
      const data = canvas.getContext('2d')!.getImageData(Math.round(area.x * dpr), Math.round(area.y * dpr), width, height).data;
      const [r, g, b] = colour as number[];
      const heights: number[] = [];
      let count = 0;
      for (let px = 0; px < width; px++) {
        let column = 0;
        for (let py = 0; py < height; py++) {
          const at = (py * width + px) * 4;
          if (Math.abs(data[at] - r) <= 3 && Math.abs(data[at + 1] - g) <= 3 && Math.abs(data[at + 2] - b) <= 3) column++;
        }
        heights.push(column);
        count += column;
      }
      const runs: number[] = [];
      for (let px = 0; px < width; px++) {
        if (heights[px] === 0) continue;
        if (px > 0 && heights[px - 1] > 0) runs[runs.length - 1] = Math.max(runs[runs.length - 1], heights[px]);
        else runs.push(heights[px]);
      }
      return { count, runs };
    },
    [colour, box] as [number[], typeof box],
  );
}

/** `a` is `factor` times `b`, give or take the pixels an edge may be off by. */
function expectRatio(a: number, b: number, factor: number): void {
  expect(Math.abs(a - b * factor), `${a} is ${factor} times ${b}`).toBeLessThanOrEqual(2 + factor * 2);
}

async function canvasBox(page: Page): Promise<{ x: number; y: number }> {
  const box = await page.locator('#host .bym-canvas').boundingBox();
  if (!box) throw new Error('the canvas has no box');
  return box;
}

/** A pointer event of a finger on the canvas, at page coordinates. */
function touchEvent(page: Page, type: string, x: number, y: number, id = 31): Promise<void> {
  return page.evaluate(
    ([type, x, y, id]) => {
      document
        .querySelector('#host .bym-canvas')!
        .dispatchEvent(new PointerEvent(type as string, { pointerId: id as number, pointerType: 'touch', isPrimary: true, clientX: x as number, clientY: y as number, bubbles: true, cancelable: true }));
    },
    [type, x, y, id] as [string, number, number, number],
  );
}

/** A key pressed in the grid. */
function key(page: Page, init: KeyboardEventInit): Promise<boolean> {
  return page.evaluate((init) => {
    const event = new KeyboardEvent('keydown', { bubbles: true, cancelable: true, ...init });
    document.querySelector('#host .bym-input')!.dispatchEvent(event);
    return event.defaultPrevented;
  }, init);
}

const saved = (page: Page) => page.evaluate(async () => Array.from((await (window as any).__file.save()) as Uint8Array));

test.describe('charts are edited', () => {
  test('a chart is added from the toolbar for the selected range, selected, and drawn from its cells', async ({ page }) => {
    await mount(page, await book());
    await view(page, 'view.select(api.parseRange("A1:B4"))');
    const button = page.locator('#host [data-command="chart"]');
    await expect(button).toHaveAttribute('aria-label', 'Insert chart');
    await button.click();
    await page.locator('#host .bym-popover').getByText('Column', { exact: true }).click();
    const list = await charts(page);
    expect(list.length).toBe(1);
    expect([list[0].type, list[0].editable, list[0].ofFile, list[0].legend]).toEqual(['column', 'all', false, 'r']);
    expect(list[0].range).toEqual({ top: 0, left: 0, bottom: 3, right: 1 });
    expect(list[0].series).toEqual([{ nameRef: 'Sayfa1!$B$1', categories: 'Sayfa1!$A$2:$A$4', values: 'Sayfa1!$B$2:$B$4' }]);
    // Beside the range: two columns right of it, at its first row.
    expect(list[0].anchor.from).toEqual({ col: 3, colOff: 0, row: 0, rowOff: 0 });
    expect(await view(page, 'view.selectedChart')).toBe(0);
    await expect(page.locator('#host .bym-live')).toHaveText('Chart added');

    // Put where a phone shows it, in one colour, against a fixed axis: the columns are the cells.
    await view(page, `(view.moveChart(0, ${JSON.stringify(HOME)}), view.updateChart(0, { legend: 'none', series: [{ from: 0, color: '#00B050' }], axisBounds: { min: 0, max: 100 } }))`);
    const green = await ink(page, GREEN, FRAME);
    expect(green.runs.length, 'three columns in the colour of the series').toBe(3);
    expectRatio(green.runs[1], green.runs[0], 2);
    expectRatio(green.runs[2], green.runs[0], 4);
    // The chart is selected: a frame with handles in the colour of the selection.
    const corner = await ink(page, BLUE, { x: FRAME.x - 5, y: FRAME.y - 5, width: 10, height: 10 });
    expect(corner.count, 'a handle at the corner of the chart').toBeGreaterThan(8);
    await view(page, 'view.selectChart(undefined)');
    expect((await ink(page, BLUE, { x: FRAME.x - 5, y: FRAME.y + FRAME.height - 5, width: 10, height: 10 })).count, 'no handle once nothing is selected').toBe(0);

    // Three steps back and there is no chart; forward again and it is as it was.
    await view(page, '(view.undo(), view.undo(), view.undo())');
    expect((await charts(page)).length).toBe(0);
    expect((await ink(page, GREEN, FRAME)).count).toBe(0);
    await view(page, '(view.redo(), view.redo(), view.redo())');
    expect((await ink(page, GREEN, FRAME)).runs.length).toBe(3);
  });

  test('a chart is selected with a click, dragged to another place, sized by a handle, moved with the arrows and deleted', async ({ page, hasTouch }) => {
    test.skip(hasTouch, MOUSE_ONLY);
    await mount(page, await book());
    await addPlain(page);
    const box = await canvasBox(page);
    const centre = { x: box.x + FRAME.x + FRAME.width / 2, y: box.y + FRAME.y + FRAME.height / 2 };
    await page.mouse.click(centre.x, centre.y);
    expect(await view(page, 'view.selectedChart')).toBe(0);
    await expect(page.locator('#host .bym-live')).toHaveText('Chart selected');
    // A cell beside it lets go of the chart, and is the active cell.
    await page.mouse.click(box.x + FRAME.x + FRAME.width + 100, box.y + HEADER_HEIGHT + 10);
    expect(await view(page, 'view.selectedChart')).toBeUndefined();

    // Dragged one column right and two rows down.
    await page.mouse.move(centre.x, centre.y);
    await page.mouse.down();
    await page.mouse.move(centre.x + 20, centre.y + 10, { steps: 2 });
    await page.mouse.move(centre.x + COLUMN_WIDTH, centre.y + 2 * ROW_HEIGHT, { steps: 4 });
    await page.mouse.up();
    let anchor = (await charts(page))[0].anchor;
    expect([anchor.from.col, anchor.from.row, anchor.to.col, anchor.to.row]).toEqual([1, 7, 5, 20]);
    await expect(page.locator('#host .bym-live')).toHaveText('Chart moved');
    expect((await ink(page, GREEN, { ...FRAME, x: FRAME.x + COLUMN_WIDTH, y: FRAME.y + 2 * ROW_HEIGHT })).runs.length, 'the columns are drawn where the chart is now').toBe(3);

    // Its bottom right handle, dragged one column left and one row up: the other corner stays.
    const handle = { x: box.x + FRAME.x + COLUMN_WIDTH + FRAME.width, y: box.y + FRAME.y + 2 * ROW_HEIGHT + FRAME.height };
    await page.mouse.move(handle.x, handle.y);
    await page.mouse.down();
    await page.mouse.move(handle.x - 30, handle.y - 10, { steps: 2 });
    await page.mouse.move(handle.x - COLUMN_WIDTH, handle.y - ROW_HEIGHT, { steps: 4 });
    await page.mouse.up();
    anchor = (await charts(page))[0].anchor;
    expect([anchor.from.col, anchor.from.row, anchor.to.col, anchor.to.row]).toEqual([1, 7, 4, 19]);

    // The arrows move the selected chart by ten pixels; Escape lets go of it; Ctrl+Alt+5 selects it again.
    expect(await key(page, { key: 'ArrowRight' })).toBe(true);
    anchor = (await charts(page))[0].anchor;
    expect([anchor.from.col, anchor.from.colOff]).toEqual([1, 10 * 9525]);
    await key(page, { key: 'Escape' });
    expect(await view(page, 'view.selectedChart')).toBeUndefined();
    await key(page, { key: '5', code: 'Digit5', ctrlKey: true, altKey: true });
    expect(await view(page, 'view.selectedChart')).toBe(0);
    // Delete deletes it; undo brings it back where it was.
    await key(page, { key: 'Delete' });
    expect((await charts(page)).length).toBe(0);
    await expect(page.locator('#host .bym-live')).toHaveText('Chart deleted');
    await view(page, 'view.undo()');
    anchor = (await charts(page))[0].anchor;
    expect([anchor.from.col, anchor.from.colOff, anchor.from.row]).toEqual([1, 10 * 9525, 7]);
  });

  test('with a finger: a tap selects the chart, a drag moves it and a handle sizes it', async ({ page, hasTouch }) => {
    test.skip(!hasTouch, TOUCH_ONLY);
    await mount(page, await book());
    await addPlain(page);
    const box = await canvasBox(page);
    const centre = { x: box.x + FRAME.x + FRAME.width / 2, y: box.y + FRAME.y + FRAME.height / 2 };
    await touchEvent(page, 'pointerdown', centre.x, centre.y);
    await touchEvent(page, 'pointerup', centre.x, centre.y);
    expect(await view(page, 'view.selectedChart')).toBe(0);
    // The finger on the selected chart moves it: one column right, one row down.
    await touchEvent(page, 'pointerdown', centre.x, centre.y, 32);
    await touchEvent(page, 'pointermove', centre.x + 30, centre.y + 12, 32);
    await touchEvent(page, 'pointermove', centre.x + COLUMN_WIDTH, centre.y + ROW_HEIGHT, 32);
    await touchEvent(page, 'pointerup', centre.x + COLUMN_WIDTH, centre.y + ROW_HEIGHT, 32);
    let anchor = (await charts(page))[0].anchor;
    expect([anchor.from.col, anchor.from.row, anchor.to.col, anchor.to.row]).toEqual([1, 6, 5, 19]);
    // Its top left handle, one column back and one row up: the chart grows that way.
    const handle = { x: box.x + FRAME.x + COLUMN_WIDTH, y: box.y + FRAME.y + ROW_HEIGHT };
    await touchEvent(page, 'pointerdown', handle.x + 3, handle.y + 3, 33);
    await touchEvent(page, 'pointermove', handle.x - 20, handle.y - 8, 33);
    await touchEvent(page, 'pointermove', handle.x + 3 - COLUMN_WIDTH, handle.y + 3 - ROW_HEIGHT, 33);
    await touchEvent(page, 'pointerup', handle.x + 3 - COLUMN_WIDTH, handle.y + 3 - ROW_HEIGHT, 33);
    anchor = (await charts(page))[0].anchor;
    expect([anchor.from.col, anchor.from.row, anchor.to.col, anchor.to.row]).toEqual([0, 5, 5, 19]);
    // A tap on a cell beside it lets go of the chart.
    await touchEvent(page, 'pointerdown', box.x + HEADER_WIDTH + 30, box.y + HEADER_HEIGHT + 10, 34);
    await touchEvent(page, 'pointerup', box.x + HEADER_WIDTH + 30, box.y + HEADER_HEIGHT + 10, 34);
    expect(await view(page, 'view.selectedChart')).toBeUndefined();
  });

  test('the dialog of a chart changes its type to a pie and gives it a title; what was only looked at is no step', async ({ page, hasTouch }) => {
    await mount(page, await book());
    await addPlain(page);
    if (hasTouch) expect(await view(page, 'view.openChartDialog(0)')).toBe(true);
    else {
      const box = await canvasBox(page);
      await page.mouse.dblclick(box.x + FRAME.x + FRAME.width / 2, box.y + FRAME.y + FRAME.height / 2);
    }
    await expect(dialog(page)).toBeVisible();
    await expect(dialog(page)).toHaveAttribute('role', 'dialog');
    await expect(field(page, 'type')).toHaveValue('column');
    await expect(field(page, 'range')).toHaveValue('A1:B4');
    await expect(field(page, 'seriesName')).toHaveValue('=$B$1');
    await expect(field(page, 'seriesValues')).toHaveAttribute('aria-label', 'Values of series 1');
    // Confirmed as it was opened: nothing changes and there is nothing more to undo.
    const before = await view(page, 'view.history.canUndo && JSON.stringify(view.charts())');
    await dialog(page).locator('[data-bym-action="ok"]').click();
    await expect(dialog(page)).toHaveCount(0);
    expect(await view(page, 'JSON.stringify(view.charts())')).toBe(before);

    expect(await view(page, 'view.openChartDialog(0)')).toBe(true);
    await field(page, 'type').selectOption('pie');
    await expect(field(page, 'minimum')).toBeHidden();
    await field(page, 'title').fill('Pay');
    await field(page, 'seriesOwnColor').uncheck();
    await dialog(page).locator('[data-bym-action="ok"]').click();
    await expect(dialog(page)).toHaveCount(0);
    const chart = (await charts(page))[0];
    expect([chart.type, chart.title, chart.series[0].color]).toEqual(['pie', 'Pay', undefined]);
    // Slices in the colours of the theme, and no column.
    expect((await ink(page, GREEN, FRAME)).count).toBe(0);
    for (const accent of [[68, 114, 196], [237, 125, 49], [165, 165, 165]]) expect((await ink(page, accent, FRAME)).count, `a slice in ${accent}`).toBeGreaterThan(50);
    expect(await view(page, 'view.getChartState().texts')).toContain('Pay');
    // One step: undo is the column chart again.
    await view(page, 'view.undo()');
    expect((await charts(page))[0].type).toBe('column');
    expect((await ink(page, GREEN, FRAME)).runs.length).toBe(3);

    // A range that is none is said in the dialog, which stays open; another one makes the series anew.
    expect(await view(page, 'view.openChartDialog(0)')).toBe(true);
    await field(page, 'range').fill('nowhere');
    await dialog(page).locator('[data-bym-action="ok"]').click();
    await expect(dialog(page).locator('[role="alert"]')).toHaveText('This is not a range of cells');
    await field(page, 'range').fill('A1:B3');
    await dialog(page).locator('[data-bym-action="ok"]').click();
    await expect(dialog(page)).toHaveCount(0);
    expect((await charts(page))[0].series[0].values).toBe('Sayfa1!$B$2:$B$3');
    expect((await ink(page, GREEN, FRAME)).runs.length, 'two columns, in the colour the series had').toBe(2);
  });

  test('cells are pointed at for the range of a chart while its dialog is open', async ({ page, hasTouch }) => {
    test.skip(hasTouch, MOUSE_ONLY);
    await mount(page, await book());
    await addPlain(page);
    expect(await view(page, 'view.openChartDialog(0)')).toBe(true);
    await field(page, 'range').focus();
    const box = await canvasBox(page);
    const cell = (col: number, row: number) => ({ x: box.x + HEADER_WIDTH + (col + 0.5) * COLUMN_WIDTH, y: box.y + HEADER_HEIGHT + (row + 0.5) * ROW_HEIGHT });
    await page.mouse.move(cell(0, 0).x, cell(0, 0).y);
    await page.mouse.down();
    await page.mouse.move(cell(1, 1).x, cell(1, 1).y, { steps: 3 });
    await page.mouse.move(cell(1, 2).x, cell(1, 2).y, { steps: 3 });
    await page.mouse.up();
    await expect(field(page, 'range')).toHaveValue('A1:B3');
    await dialog(page).locator('[data-bym-action="ok"]').click();
    await expect(dialog(page)).toHaveCount(0);
    expect((await charts(page))[0].range).toEqual({ top: 0, left: 0, bottom: 2, right: 1 });
  });

  test('a chart that was added is in the file that is saved, and follows a row that is inserted', async ({ page }) => {
    await mount(page, await book());
    await addPlain(page);
    const bytes = await saved(page);
    await mount(page, bytes);
    const list = await charts(page);
    expect(list.length).toBe(1);
    expect([list[0].type, list[0].ofFile, list[0].editable]).toEqual(['column', true, 'all']);
    let green = await ink(page, GREEN, FRAME);
    expect(green.runs.length, 'the chart of the file is drawn').toBe(3);
    const low = green.runs[0];
    // A row inside its values, with a number: the range grows, the chart moves down a row and shows four columns.
    await view(page, '(view.insertRows(2, 1), view.setCellInput(2, 1, "80"), view.setCellInput(2, 0, "yeni"))');
    expect((await charts(page))[0].series[0].values).toBe('Sayfa1!$B$2:$B$5');
    green = await ink(page, GREEN, { ...FRAME, y: FRAME.y + ROW_HEIGHT });
    expect(green.runs.length, 'four columns').toBe(4);
    expectRatio(green.runs[1], low, 8);
    // Saved again and read again: the file says the same.
    await mount(page, await saved(page));
    expect((await charts(page))[0].series[0].values).toBe('Sayfa1!$B$2:$B$5');
    expect((await ink(page, GREEN, { ...FRAME, y: FRAME.y + ROW_HEIGHT })).runs.length).toBe(4);
    // With everything of a chart undone the file is the file again.
    await mount(page, await book());
    const original = await saved(page);
    await addPlain(page);
    await view(page, '(view.undo(), view.undo())');
    expect(await saved(page)).toEqual(original);
  });

  test('a read-only view adds no chart, selects none and opens no dialog', async ({ page, hasTouch }) => {
    const filled = await (async () => {
      await mount(page, await book());
      await addPlain(page);
      return saved(page);
    })();
    await mount(page, filled, { readOnly: true });
    await expect(page.locator('#host [data-command="chart"]')).toBeDisabled();
    expect(await view(page, 'view.addChart({ type: "column", range: { top: 0, left: 0, bottom: 3, right: 1 } })')).toBe(-1);
    expect((await charts(page)).length).toBe(1);
    const box = await canvasBox(page);
    const centre = { x: box.x + FRAME.x + FRAME.width / 2, y: box.y + FRAME.y + FRAME.height / 2 };
    if (hasTouch) {
      await touchEvent(page, 'pointerdown', centre.x, centre.y);
      await touchEvent(page, 'pointerup', centre.x, centre.y);
    } else await page.mouse.click(centre.x, centre.y);
    expect(await view(page, 'view.selectedChart')).toBeUndefined();
    expect(await view(page, 'view.openChartDialog(0)')).toBe(false);
    await key(page, { key: 'Delete' });
    expect((await charts(page)).length).toBe(1);
    expect((await ink(page, GREEN, FRAME)).runs.length, 'the chart is shown all the same').toBe(3);
  });
  test('a chart that is being dragged is let go when a step is undone under it; nothing is moved when the pointer is lifted', async ({ page, hasTouch }) => {
    test.skip(hasTouch, MOUSE_ONLY);
    await mount(page, await book());
    await addPlain(page);
    // A second chart behind the first in the list, and a move that can be undone.
    await view(page, `(view.addChart({ type: 'line', range: { top: 0, left: 0, bottom: 3, right: 1 }, anchor: { top: 25, left: 0, bottom: 35, right: 3 } }), view.selectChart(undefined))`);
    const box = await canvasBox(page);
    const centre = { x: box.x + FRAME.x + FRAME.width / 2, y: box.y + FRAME.y + FRAME.height / 2 };
    const anchors = async () => JSON.stringify((await charts(page)).map((chart) => [chart.type, chart.anchor.from.col, chart.anchor.from.row]));
    await page.mouse.move(centre.x, centre.y);
    await page.mouse.down();
    await page.mouse.move(centre.x + 40, centre.y + 30, { steps: 3 });
    expect(await view(page, 'view.hasPendingInput()'), 'a drag of a chart is something under way').toBe(true);
    // The step that added the second chart is taken back while the first is held.
    await view(page, 'view.undo()');
    expect(await view(page, 'view.hasPendingInput()')).toBe(false);
    const undone = await anchors();
    await page.mouse.move(centre.x + COLUMN_WIDTH, centre.y + 2 * ROW_HEIGHT, { steps: 3 });
    await page.mouse.up();
    expect(await anchors(), 'no chart is moved by the pointer that is lifted').toBe(undone);
    // The same when another sheet is shown under the drag.
    await view(page, 'view.insertSheet()');
    await view(page, 'view.setActiveSheet(0)');
    await page.mouse.move(centre.x, centre.y);
    await page.mouse.down();
    await page.mouse.move(centre.x + 40, centre.y + 30, { steps: 3 });
    await view(page, 'view.setActiveSheet(1)');
    await page.mouse.up();
    await view(page, 'view.setActiveSheet(0)');
    expect(await anchors()).toBe(undone);
    // And when the view becomes read-only: the chart is no longer selected either.
    await page.mouse.move(centre.x, centre.y);
    await page.mouse.down();
    await page.mouse.move(centre.x + 40, centre.y + 30, { steps: 3 });
    await view(page, 'view.setReadOnly(true)');
    await page.mouse.up();
    expect(await anchors()).toBe(undone);
    expect(await view(page, 'view.selectedChart')).toBeUndefined();
  });

  test('with a chart selected, copy, cut and paste leave the cells alone and say that a chart is not copied; Tab leaves the grid', async ({ page }) => {
    await mount(page, await book());
    await addPlain(page);
    await view(page, '(view.select(api.parseRange("A1:B4")), view.selectChart(0))');
    const fire = (type: string) =>
      page.evaluate((type) => {
        const data = new DataTransfer();
        data.setData('text/plain', 'pasted');
        const event = new ClipboardEvent(type, { clipboardData: data, bubbles: true, cancelable: true });
        document.querySelector('#host .bym-input')!.dispatchEvent(event);
        return event.defaultPrevented;
      }, type);
    const cells = () => view(page, 'JSON.stringify([0, 1, 2, 3].map((row) => [api.getCell(view.workbook.sheets[0], row, 0)?.value, api.getCell(view.workbook.sheets[0], row, 1)?.value]))');
    const before = await cells();
    for (const type of ['cut', 'copy', 'paste']) {
      expect(await fire(type), `${type} is taken`).toBe(true);
      expect(await cells(), `${type} changes no cell`).toBe(before);
      expect(await page.evaluate(() => (window as any).__events.filter((event: any) => event.type === 'notice').slice(-1)[0]?.message), type).toBe('A chart cannot be copied or pasted yet');
    }
    expect((await charts(page)).length).toBe(1);
    // Tab is not the chart's: the focus goes on as it does from the cells.
    expect(await key(page, { key: 'Tab' })).toBe(false);
    expect(await view(page, 'view.selectedChart')).toBe(0);
    // Ctrl+Alt+5 goes from chart to chart, and to none after the last.
    await view(page, `view.addChart({ type: 'line', range: { top: 0, left: 0, bottom: 3, right: 1 }, anchor: { top: 25, left: 0, bottom: 35, right: 3 } })`);
    await view(page, 'view.selectChart(undefined)');
    const next = async () => {
      await key(page, { key: '5', code: 'Digit5', ctrlKey: true, altKey: true });
      return view(page, 'view.selectedChart');
    };
    expect([await next(), await next(), await next(), await next()]).toEqual([0, 1, undefined, 0]);
    // Without a chart selected the clipboard is the cells' again.
    await view(page, 'view.selectChart(undefined)');
    await fire('cut');
    expect(await cells()).not.toBe(before);
  });

  test('with a chart selected nothing is typed into the cells and no key formats, clears or edits them; Escape gives the keys back to the cells', async ({ page }) => {
    await mount(page, await book());
    await addPlain(page);
    await view(page, '(view.select(api.parseRange("A1:B4")), view.selectChart(0), view.focus())');
    const cells = () => view(page, 'JSON.stringify([0, 1, 2, 3].map((row) => [0, 1].map((col) => { const cell = api.getCell(view.workbook.sheets[0], row, col); return cell ? [cell.value, cell.style] : null; })))');
    const before = await cells();
    const untouched = async (what: string) => {
      expect(await cells(), `${what}: no cell changed`).toBe(before);
      expect(await view(page, 'view.isEditing'), `${what}: no cell is edited`).toBe(false);
      expect(await view(page, 'view.selectedChart'), `${what}: the chart stays selected`).toBe(0);
      expect((await charts(page)).length, `${what}: the chart is there`).toBe(1);
      expect(await view(page, 'JSON.stringify(view.selection.range)'), `${what}: the cells that are selected`).toBe(JSON.stringify({ top: 0, left: 0, bottom: 3, right: 1 }));
    };
    // Typing: the key is taken and nothing comes of it.
    expect(await key(page, { key: 'x' })).toBe(true);
    await untouched('a letter');
    await page.keyboard.type('hello');
    await untouched('typing');
    expect(await page.evaluate(() => (document.querySelector('#host .bym-input') as HTMLTextAreaElement).value), 'nothing of what was typed is left in the input').not.toContain('hello');
    for (const [what, init] of [
      ['F2', { key: 'F2' }],
      ['Shift+F2', { key: 'F2', shiftKey: true }],
      ['Ctrl+B', { key: 'b', ctrlKey: true }],
      ['Ctrl+I', { key: 'i', ctrlKey: true }],
      ['Ctrl+U', { key: 'u', ctrlKey: true }],
      ['Cmd+B', { key: 'b', metaKey: true }],
      ['Ctrl+A', { key: 'a', ctrlKey: true }],
      ['Ctrl+Delete', { key: 'Delete', ctrlKey: true }],
      ['Alt+Backspace', { key: 'Backspace', altKey: true }],
      ['Home', { key: 'Home' }],
      ['Ctrl+ArrowDown', { key: 'ArrowDown', ctrlKey: true }],
      ['PageDown', { key: 'PageDown' }],
    ] as [string, KeyboardEventInit][]) {
      expect(await key(page, init), `${what} is taken`).toBe(true);
      await untouched(what);
    }
    // Ctrl with + and - is the zoom of the browser: not taken, and the rows that are selected under the chart stay.
    await view(page, '(view.select({ top: 1, left: 0, bottom: 1, right: 16383 }), view.selectChart(0))');
    expect(await key(page, { key: '-', ctrlKey: true })).toBe(false);
    expect(await key(page, { key: '+', ctrlKey: true })).toBe(false);
    expect(await cells(), 'no row went and none came').toBe(before);
    await view(page, '(view.select(api.parseRange("A1:B4")), view.selectChart(0))');
    // Shift+Delete is "cut" on Windows: it is left to the browser, and the chart is not deleted by it.
    expect(await key(page, { key: 'Delete', shiftKey: true })).toBe(false);
    await untouched('Shift+Delete');
    // An input method: its keys are not the view's to take, and what it composes goes nowhere.
    await page.evaluate(() => {
      const input = document.querySelector('#host .bym-input') as HTMLTextAreaElement;
      input.dispatchEvent(new KeyboardEvent('keydown', { key: 'Process', keyCode: 229, bubbles: true, cancelable: true } as KeyboardEventInit));
      input.dispatchEvent(new CompositionEvent('compositionstart', { bubbles: true }));
      input.value = 'か';
      input.dispatchEvent(new InputEvent('input', { inputType: 'insertCompositionText', data: 'か', isComposing: true, bubbles: true }));
      input.dispatchEvent(new CompositionEvent('compositionend', { data: 'か', bubbles: true }));
      input.dispatchEvent(new InputEvent('input', { inputType: 'insertText', data: 'か', bubbles: true }));
    });
    await untouched('an input method');
    expect(await page.evaluate(() => (document.querySelector('#host .bym-input') as HTMLTextAreaElement).value)).not.toContain('か');
    // Undo is still the workbook's.
    await view(page, 'view.moveChart(0, { top: 6, left: 0, bottom: 18, right: 3 })');
    expect(await key(page, { key: 'z', ctrlKey: true })).toBe(true);
    expect((await charts(page))[0].anchor.from.row).toBe(5);
    // Escape lets go of the chart: from then on what is typed is typed into the active cell.
    await view(page, 'view.selectChart(0)');
    expect(await key(page, { key: 'Escape' })).toBe(true);
    expect(await view(page, 'view.selectedChart')).toBe(undefined);
    await page.keyboard.type('q');
    expect(await view(page, 'view.isEditing')).toBe(true);
    await page.keyboard.press('Escape');
    // Plain Delete deletes the chart, and only it.
    await view(page, 'view.selectChart(0)');
    expect(await key(page, { key: 'Delete' })).toBe(true);
    expect((await charts(page)).length).toBe(0);
    expect(await cells()).toBe(before);
  });

  test('a long press on a cell opens the menu of the cells and lets go of the chart that was selected', async ({ page }) => {
    await mount(page, await book());
    await addPlain(page);
    await view(page, 'view.selectChart(0)');
    const box = await canvasBox(page);
    // Cell B2, above the chart.
    const x = box.x + HEADER_WIDTH + COLUMN_WIDTH * 1.5;
    const y = box.y + HEADER_HEIGHT + ROW_HEIGHT * 1.5;
    await touchEvent(page, 'pointerdown', x, y);
    await expect(page.locator('#host .bym-menu')).toBeVisible();
    expect(await view(page, 'view.selectedChart'), 'the menu is about the cells').toBe(undefined);
  });

  test('a read-only view selects no chart by key or by call, and its arrow keys move the cells', async ({ page }) => {
    await mount(page, await book());
    await addPlain(page);
    const bytes = await saved(page);
    await mount(page, bytes, { readOnly: true });
    await view(page, '(view.select(api.parseRange("B2")), view.focus())');
    await key(page, { key: '5', code: 'Digit5', ctrlKey: true, altKey: true });
    expect(await view(page, 'view.selectedChart')).toBeUndefined();
    await view(page, 'view.selectChart(0)');
    expect(await view(page, 'view.selectedChart')).toBeUndefined();
    await key(page, { key: 'ArrowRight' });
    expect(await view(page, 'api.rangeName(view.selection.range)')).toBe('C2');
    // Made read-only with a chart selected: it is let go of, and the arrows are the cells' at once.
    await mount(page, bytes);
    await view(page, '(view.select(api.parseRange("B2")), view.selectChart(0), view.setReadOnly(true), view.focus())');
    expect(await view(page, 'view.selectedChart')).toBeUndefined();
    await key(page, { key: 'ArrowDown' });
    expect(await view(page, 'api.rangeName(view.selection.range)')).toBe('B3');
    expect((await charts(page))[0].anchor.from).toEqual({ col: 0, colOff: 0, row: 5, rowOff: 0 });
  });

  test('what cannot be done to a chart is said in the language of the view', async ({ page }) => {
    const messages = [
      'Cannot add a series to a chart of this type',
      'Cannot add, remove or reorder the series of a stock chart',
      'Cannot add, remove or reorder the series of this chart: its part holds content bound to their order',
      'Cannot change the series of a chart of several types',
      'Cannot change how the series of this chart are grouped',
      'This chart has no such axis',
      'A chart has at most 255 series',
      'A sheet has at most 1000 charts',
      'The title cannot be longer than 255 characters',
      'The name of a series holds a character a file cannot hold',
      'Cannot change the sheet: a reference of a chart cannot be read',
      'Cannot change the type of this chart: its part holds formatting that another type cannot keep',
      'Cannot change this chart: its part holds references the model does not, so it is only moved and deleted',
      '"x" is not a range of cells of this workbook',
      'A series needs a range of values',
      'No chart at index 3',
    ];
    const said = async (locale: string) => {
      await mount(page, await book(), { locale });
      return page.evaluate((messages) => messages.map((message) => (window as any).__editor.view.localizeError(new RangeError(message))), messages);
    };
    const english = await said('en-US');
    const turkish = await said('tr');
    const generic = [await view(page, 'view.localizeError(new RangeError("nothing anybody knows"))')];
    expect(english).toEqual([
      'The series of this chart cannot be added, removed or reordered: its type or its file does not allow it',
      'The series of this chart cannot be added, removed or reordered: its type or its file does not allow it',
      'The series of this chart cannot be added, removed or reordered: its type or its file does not allow it',
      'The series of this chart cannot be added, removed or reordered: its type or its file does not allow it',
      'The series of this type of chart cannot be stacked',
      'This chart has no such axis',
      'A chart has at most 255 series',
      'No more charts can be added here',
      'This text cannot be longer than 255 characters',
      'The text holds a character a file cannot hold',
      'The sheet cannot be changed: a chart names it in a reference that cannot be read',
      'The type of this chart cannot be changed: its file holds formatting another type cannot keep',
      'This chart can be moved and deleted, not changed: its file holds what cannot be kept',
      'This is not a range of cells',
      'A series needs a range of values',
      'No chart is selected',
    ]);
    // Each has words of its own in Turkish: none is the same as in English, none is the answer for what is not known.
    turkish.forEach((message: string, i: number) => {
      expect(message, messages[i]).not.toBe(english[i]);
      expect(message, messages[i]).not.toBe(generic[0]);
    });
    expect(turkish[4]).toBe('Bu grafik türünün serileri yığılamaz');
  });
});
